#!/usr/bin/env node
// Regenerates src/icons/brands.generated.ts from the simple-icons devDependency. Run this after
// editing BRAND_SLUGS below (e.g. to add a newly-requested actor logo) — never hand-edit the
// generated file. simple-icons is CC0-licensed brand marks, kept as a devDependency only: nothing
// here ships at runtime except the tiny path+hex pairs baked into the generated file.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ICONS_DIR = path.join(__dirname, "..", "node_modules", "simple-icons", "icons");
const DATA_PATH = path.join(__dirname, "..", "node_modules", "simple-icons", "data", "simple-icons.json");
const OUT_PATH = path.join(__dirname, "..", "src", "icons", "brands.generated.ts");

// Curated external-system/actor brands actually present in the current simple-icons release —
// some well-known marks (AWS, Azure, Slack, OpenAI, Twilio, SendGrid) have been withdrawn from the
// package on trademark request and simply aren't available; unset/unknown slugs fall back to the
// generic external_system icon, so a missing brand degrades gracefully rather than erroring.
const BRAND_SLUGS = [
  "stripe",
  "paypal",
  "github",
  "gitlab",
  "bitbucket",
  "githubactions",
  "circleci",
  "googlecloud",
  "digitalocean",
  "render",
  "cloudflare",
  "vercel",
  "netlify",
  "postgresql",
  "mysql",
  "mariadb",
  "sqlite",
  "mongodb",
  "redis",
  "influxdb",
  "apachekafka",
  "rabbitmq",
  "docker",
  "kubernetes",
  "terraform",
  "nginx",
  "elasticsearch",
  "elastic",
  "grafana",
  "prometheus",
  "newrelic",
  "datadog",
  "sentry",
  "pagerduty",
  "anthropic",
  "auth0",
  "okta",
  "firebase",
  "supabase",
  "jira",
  "confluence",
  "figma",
  "zendesk",
  "hubspot",
];

async function main() {
  const rawData = JSON.parse(await readFile(DATA_PATH, "utf-8"));
  const bySlug = new Map(rawData.map((entry) => [entry.slug, entry]));

  const entries = [];
  for (const slug of BRAND_SLUGS) {
    const meta = bySlug.get(slug);
    if (!meta) throw new Error(`simple-icons has no entry for slug "${slug}" — check BRAND_SLUGS`);
    const svg = await readFile(path.join(ICONS_DIR, `${slug}.svg`), "utf-8");
    const match = svg.match(/<path d="([^"]+)"/);
    if (!match) throw new Error(`could not extract path data from ${slug}.svg`);
    entries.push({ slug, title: meta.title, hex: meta.hex, path: match[1] });
  }
  entries.sort((a, b) => a.slug.localeCompare(b.slug));

  const body = entries
    .map(
      (entry) =>
        `  ${entry.slug}: { title: ${JSON.stringify(entry.title)}, hex: ${JSON.stringify(entry.hex)}, path: ${JSON.stringify(entry.path)} },`,
    )
    .join("\n");

  const contents = `// Generated by scripts/update-brand-icons.mjs from the simple-icons package — do not hand-edit.
// To add a brand: append its slug to BRAND_SLUGS in that script and rerun it.
export interface BrandIconEntry {
  title: string;
  hex: string;
  path: string;
}

export const BRAND_ICONS: Record<string, BrandIconEntry> = {
${body}
};
`;
  await writeFile(OUT_PATH, contents);
  console.log(`Wrote ${entries.length} brand icons to ${path.relative(process.cwd(), OUT_PATH)}`);
}

main();
